arguments.command:
cd $env:TEMP
Remove-Item -Recurse -Force symlink_test_dest -ErrorAction SilentlyContinue
mkdir symlink_test_src -Force | Out-Null
try {
  New-Item -ItemType SymbolicLink -Path symlink_test_dest -Target symlink_test_src -ErrorAction Stop | Out-Null
  Write-Output "PowerShell symlink: SUCCESS"
  (Get-Item symlink_test_dest).LinkType
} catch {
  Write-Output "PowerShell symlink FAILED: $($_.Exception.Message)"
}
Remove-Item -Recurse -Force symlink_test_dest, symlink_test_src -ErrorAction SilentlyContinue

